export const IVERILOG_WASM_ERROR_CODES = [
    'INVALID_INPUT',
    'NOT_IMPLEMENTED',
    'WORKER_START',
    'RUNTIME_LOAD',
    'WASM_ASSET_MISSING',
    'TIMEOUT',
    'PROTOCOL_MISMATCH',
    'WORKER_EXIT',
];
export class IverilogWasmError extends Error {
    code;
    constructor(code, message, options) {
        super(message, options);
        this.name = 'IverilogWasmError';
        this.code = code;
    }
}
